import {
  FeatureSetType,
  MiiPagedFeatureSet
} from "../components/MiiPagedFeatureSet";
import EditorIcons from "../../constants/EditorIcons";
import {
  MiiSkinColorTable,
  MiiSwitchSkinColorList,
  SwitchMiiColorTable
} from "../../constants/ColorTables";
import type { TabRenderInit } from "../../constants/TabRenderType";
import { ArrayNum } from "../../util/Numbers";
import { BodyUpdateType, RenderPart } from "../../class/MiiEditor";
import {
  makeSeparatorFSI,
  makeSeparatorGapThinDesktop,
  makeSeparatorGapThinFSI,
  makeSeparatorGapThinLaptop,
  MiiSwitchColorTable,
  MiiSwitchSkinColorTable,
  rearrangeArray
} from "../../constants/MiiFeatureTable";

import { _ } from "../../util/Lang";
const __ = _();

export function HeadTab(data: TabRenderInit) {
  data.container.append(
    MiiPagedFeatureSet({
      mii: data.mii,
      onChange: data.callback,
      entries: {
        facelineType: {
          label: data.useAccessibility ? __("Shape") : EditorIcons.face,
          items: ArrayNum(12).map((k) => ({
            type: FeatureSetType.Icon,
            value: k,
            icon: data.icons.face[k],
            part: RenderPart.Head,
            bodyUpdateType: BodyUpdateType.None
          }))
        },
        facelineMake: {
          label: data.useAccessibility ? __("Makeup") : EditorIcons.face_makeup,
          items: ArrayNum(12).map((k) => ({
            type: FeatureSetType.Icon,
            value: k,
            icon: data.icons.makeup[k],
            part: RenderPart.Head,
            bodyUpdateType: BodyUpdateType.None
          }))
        },
        facelineWrinkle: {
          label: data.useAccessibility
            ? __("Wrinkles")
            : EditorIcons.face_wrinkles,
          items: ArrayNum(12).map((k) => ({
            type: FeatureSetType.Icon,
            value: k,
            icon: data.icons.wrinkles[k],
            part: RenderPart.Head,
            bodyUpdateType: BodyUpdateType.None
          }))
        },
        facelineColor: {
          label: data.useAccessibility ? __("Color") : EditorIcons.color,
          items: [
            ...ArrayNum(6).map((k) => ({
              type: FeatureSetType.Icon,
              value: k,
              color: MiiSkinColorTable[k],
              part: RenderPart.Head,
              bodyUpdateType: BodyUpdateType.ClothingUpdate
            })),
            makeSeparatorFSI(),
            ...rearrangeArray(
              ArrayNum(10).map((k) => ({
                type: FeatureSetType.Icon,
                value: k,
                color: MiiSwitchSkinColorList[k],
                part: RenderPart.Head,
                bodyUpdateType: BodyUpdateType.ClothingUpdate
              })),
              MiiSwitchSkinColorTable,
              makeSeparatorGapThinFSI
            )
          ]
        },
        facePaintColor: {
          label: data.useAccessibility
            ? __("Face Paint")
            : EditorIcons.face_paint,
          header: __(
            "%1 is a CUSTOM property, and will not transfer to any other data formats.",
            // face paint warning label
            __("Face paint")
          ),
          items: [
            {
              type: FeatureSetType.Icon,
              forceRender: true,
              value: -1,
              icon: `<span class="disable-item">${__("Disabled")}</span>`,
              part: RenderPart.Head,
              bodyUpdateType: BodyUpdateType.ClothingUpdate
            },
            makeSeparatorGapThinFSI(),
            ...rearrangeArray(
              ArrayNum(100).map((k) => ({
                type: FeatureSetType.Icon,
                value: k,
                // icon: `<span style="display:flex;justify-content:center;align-items:center;position:relative;z-index:1;">${k}</span>`,
                color: SwitchMiiColorTable[k],
                part: RenderPart.Head,
                bodyUpdateType: BodyUpdateType.ClothingUpdate
              })),
              MiiSwitchColorTable,
              makeSeparatorGapThinLaptop
            )
          ]
        }
      }
    })
  );
}
