export async function pushToServer() {
  if (typeof Config.syncAPIBase !== 'string') {
    console.debug('pushToServer: Called when Config.syncAPIBase is null. Not syncing.');
    return;
  }

  const miis = await Promise.all(
    (await localforage.keys())
      .filter((k) => k.startsWith("mii-"))
      .sort((a, b) => Number(a.split("-")[1]!) - Number(b.split("-")[1]!))
      .map(async (k) => ({
        id: k,
        mii: (await localforage.getItem(k)) as string
      }))
  );

  // Push
  await fetch(Config.syncAPIBase + "sync_library", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ miis })
  })
    .then(async (e) => {
      if (!e.ok) {
        const text = await e.text();
        alert("REQ FAILED - Unable to sync library data: " + text);
        console.error("Failed to sync library data: " + e);
      }
    })
    .catch((e) => {
      alert("ERROR - Unable to sync library data: " + e);
      console.error("Failed to sync library data: " + e);
    });
}
export function choosePersonalMii(
  miiList: MiiLocalforage[],
  cancelable: boolean = false
) {
  console.assert(Config.syncAPIBase !== null);

  return new Promise((resolve) => {
    const personalMiiChooseModal = Modal.modal(
      __("Notice"),
      "",
      "body",
      {
        text: __("Confirm")
      },
      cancelable ? { text: "Cancel" } : (undefined as any)
    );
    personalMiiChooseModal.classOn("random-mii-grid");
    const container = personalMiiChooseModal.qs(".modal-body")!;
    // Hide unused elements without deleting them
    container
      .qsa("span,.flex-group *")!
      .forEach((e) => e!.style({ display: "none" }));

    container.prepend(
      new Html("span")
        .style({
          width: "100%",
          padding: "14px 18px",
          background: "var(--hover)",
          color: "var(--text)",
          border: "1px solid var(--stroke)",
          "border-radius": "6px",
          "flex-shrink": "0"
        })
        .text(
          __(
            "Choose a Mii to be your Personal Mii, which can be used across apps. This can always be changed later in Settings."
          )
        )
    );

    let randomMiiContainer = new Html("div")
      .class("random-mii-container")
      .appendTo(container);

    let count = 0;
    for (const mii of miiList) {
      let button = new Html("button")
        .append(new Html("img").attr({ src: "" }))
        .appendTo(randomMiiContainer);

      const m = new Mii(mii.mii);

      function loadIcon() {
        getMiiIcon(m, "personal_mii_icon").then((icon) => {
          playLoadSound();
          button.qs("img")?.attr({ src: icon.url }).on("load", icon.dispose);
        });
      }

      button.on("click", async () => {
        confirmPersonalMii(m, mii, personalMiiChooseModal).then((result) => {
          if (result) {
            resolve(mii.id);
          }
        });
      });

      //@ts-expect-error
      if (window.browserMitigations !== undefined) {
        // alert("browser mitigations enabled");
        setTimeout(() => {
          loadIcon();
        }, count * 50);
      } else {
        // alert("browser mitigations disabled");
        setTimeout(() => {
          loadIcon();
        }, 0);
      }

      count++;
    }
  });
}
function confirmPersonalMii(
  mii: Mii,
  miiLocalforage: MiiLocalforage,
  modalRef?: Html
) {
  console.assert(Config.syncAPIBase !== null);

  return new Promise((resolve) => {
    const miiIcon = new Html("img").style({
      opacity: "0",
      width: "210px",
      height: "210px",
      transition: "opacity 0.35s ease"
    });

    getMiiIcon(mii, "personal_mii_preview", "all_body_sugar", 210).then(
      (icon) => {
        miiIcon
          .attr({ src: icon.url })
          .style({ opacity: "1" })
          .on("load", icon.dispose);
      }
    );

    Modal.modal(
      // Confirmation message
      __("Is this OK?"),
      new Html("div")
        .style({
          margin: "0 auto",
          display: "flex",
          "flex-direction": "column",
          "align-items": "center"
        })
        .classOn("col")
        .append(miiIcon)
        .prepend(
          new Html("span").text("This will be set as your Personal Mii.")
        ),
      "body",
      // does nothing
      {
        text: "Cancel",
        callback() {
          resolve(false);
        }
      },
      {
        text: __("Close"),
        callback() {
          resolve(false);
        }
      },
      {
        text: __("Confirm"),
        type: "primary",
        async callback(e) {
          // Click the invisible "confirm" button to close the modal normally
          if (modalRef) modalRef.qs(".flex-group button")?.elm.click();
          await fetch(Config.syncAPIBase + "/personal_mii", {
            body: JSON.stringify({
              nickname: mii.nickname,
              creator: mii.creator,
              ffsd: mii.exportBase64("ffsd"),
              data: mii.exportBase64("miic"),
              studio: mii.exportBase64("studioData"),
              store_id: miiLocalforage.id
            }),
            method: "POST",
            headers: { "content-type": "application/json" }
          }).catch(undefined);
          resolve(true);
        }
      }
    );
  });
}

